"""Retained upstream multi-package validation helper; Nightly uses package_release.py."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import shutil
import struct
import subprocess

from package_release import machine

ROOT = Path(__file__).resolve().parents[1]


def package(args):
    version = (ROOT / "VERSION").read_text().strip()
    if not re.fullmatch(r"\d+\.\d+(?:\.\d+)?(?:-dev\.\d+)?", version):
        raise ValueError("Expected a stable or explicitly versioned development release")
    development = "-dev" in version
    source_commit = subprocess.check_output(
        ["git", "rev-parse", "HEAD"], cwd=ROOT, text=True).strip()
    patch_hash = hashlib.sha256((ROOT / "patches/l4d2-bridge.patch").read_bytes()).hexdigest()
    build_id = f"l4d2-{version}+{patch_hash[:16]}"
    source = args.source
    inputs = {
        "bin/dxvk_d3d9.dll": (args.client or source / "bridge/_compDebugOptimized_x86/src/client/d3d9.dll", 0x14C),
        "bin/.l4d2bridge/L4D2Bridge64.exe": (args.host64 or source / "bridge/_compDebugOptimized_x64/src/server/L4D2Bridge64.exe", 0x8664),
        "bin/.l4d2bridge/L4D2Bridge32.exe": (args.host32 or source / "bridge/_compDebugOptimized_x86_server/src/server/L4D2Bridge32.exe", 0x14C),
    }
    if bool(args.dxvk) != bool(args.dxvk_x86):
        raise ValueError("A full package needs both DXVK architectures")
    backends = {} if not args.dxvk else {
        "bin/.l4d2bridge/d3d9vk_x64.dll": (args.dxvk, 0x8664),
        "bin/.l4d2bridge/d3d9vk_x86.dll": (args.dxvk_x86, 0x14C),
    }
    for relative, (path, expected) in {**inputs, **backends}.items():
        if machine(path) != expected:
            raise ValueError(f"Wrong PE architecture: {relative}")
        if relative in inputs and build_id.encode() not in path.read_bytes():
            raise ValueError(f"Missing matching build identity: {relative}")
    host32 = inputs["bin/.l4d2bridge/L4D2Bridge32.exe"][0].read_bytes()
    pe = struct.unpack_from("<I", host32, 60)[0]
    if not struct.unpack_from("<H", host32, pe + 22)[0] & 0x20:
        raise ValueError("x86 Host must be LARGEADDRESSAWARE")
    if args.plugin and machine(args.plugin) != 0x14C:
        raise ValueError("The optional L4N plugin must be x86")
    build = None
    if args.build_info:
        build = json.loads(args.build_info.read_text())
        if build.get("build_id") != build_id or build.get("patch_sha256") != patch_hash:
            raise ValueError("Build receipt does not match current patch")
    destinations = [args.output / "l4d2-bridge-patch"]
    if backends and not args.patch_only:
        destinations.append(args.output / "l4d2-bridge")
    plugin_output = args.output / "l4d2-bridge-l4n" if args.plugin and not development else None
    if plugin_output is not None and plugin_output.exists():
        raise FileExistsError(f"Preserve the existing plugin package first: {plugin_output}")
    for output in destinations:
        if output.exists():
            raise FileExistsError(f"Preserve or move the existing package first: {output}")
    for output in destinations:
        full = output.name == "l4d2-bridge"
        output.mkdir(parents=True)
        hashes = {}
        for relative, (path, _) in {**inputs, **(backends if full else {})}.items():
            target = output / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, target)
            hashes[relative] = hashlib.sha256(target.read_bytes()).hexdigest()
        if full:
            shutil.copy2(ROOT / "config/bridge.conf", output / "bin/.l4d2bridge/bridge.conf")
        if args.plugin and development:
            relative = "optional/L4N/L4D2BridgePlugin.dll"
            target = output / relative
            target.parent.mkdir(parents=True)
            shutil.copy2(args.plugin, target)
            hashes[relative] = hashlib.sha256(target.read_bytes()).hexdigest()
        for filename in ("README.md", "CHANGELOG.md", "LDBREADME.md", "VERSION", "LICENSE", "THIRD_PARTY.md"):
            shutil.copy2(ROOT / filename, output / filename)
        for directory in ("docs", "config", "patches"):
            shutil.copytree(ROOT / directory, output / directory)
        scripts = output / "scripts"
        scripts.mkdir()
        for filename in ("analyze_api_wait.py", "analyze_color_diagnostics.py", "analyze_data_diagnostics.py"):
            shutil.copy2(ROOT / "scripts" / filename, scripts / filename)
        shutil.copy2(ROOT / "scripts/install_color_diagnostics.ps1", output / "Install-ColorDiagnostics.ps1")
        licenses = output / "licenses"
        licenses.mkdir()
        shutil.copy2(source / "bridge/LICENSE-MIT", licenses / "Bridge-MIT.txt")
        shutil.copy2(source / "bridge/ThirdPartyLicenses.txt", licenses / "Bridge-third-party.txt")
        shutil.copy2(ROOT / "licenses/DXVK-LICENSE.txt", licenses / "DXVK-LICENSE.txt")
        release_guide = f"RELEASE-V{version}.md"
        if not (ROOT / "docs" / release_guide).exists():
            release_guide = "DEVELOPMENT-V1.1.2.md"
        (output / "PATCH-INSTRUCTIONS.md").write_text(
            f"# {version}\n\nRead [release instructions](docs/{release_guide}), "
            "[configuration reference](docs/CONFIGURATION.md) and [optional L4N settings](docs/L4N-BRIDGE-CONTROLS.md). "
            "Replace all three matched Bridge binaries. The patch preserves runtime configuration/backends. "
            "The full package includes default configuration and DXVK. L4N plugin is optional. "
            "Do not run Install-ColorDiagnostics.ps1 for a normal update: it actively enables colour diagnostics.\n",
            encoding="utf-8",
        )
        receipt = {"version": version, "build_id": build_id, "patch_sha256": patch_hash,
                   "kind": "full" if full else "matched-update", "gameplay_validated": False,
                   "source_commit": source_commit,
                   "distribution": "development" if development else "release",
                   "optional_plugin": bool(args.plugin and development), "files": hashes}
        if build is not None:
            receipt["build_environment"] = build
        (output / "BUILD-INFO.json").write_text(json.dumps(receipt, indent=2) + "\n", encoding="utf-8")
        (output / "SHA256.json").write_text(json.dumps(hashes, indent=2) + "\n", encoding="utf-8")
        print(output)
    if plugin_output is not None:
        relative = "bin/neko/plugins/L4D2BridgePlugin.dll"
        target = plugin_output / relative
        target.parent.mkdir(parents=True)
        shutil.copy2(args.plugin, target)
        hashes = {relative: hashlib.sha256(target.read_bytes()).hexdigest()}
        for filename in ("VERSION", "LICENSE", "THIRD_PARTY.md"):
            shutil.copy2(ROOT / filename, plugin_output / filename)
        (plugin_output / "docs").mkdir()
        shutil.copy2(ROOT / "docs/L4N-BRIDGE-CONTROLS.md", plugin_output / "docs/L4N-BRIDGE-CONTROLS.md")
        (plugin_output / "README.md").write_text(
            f"# Optional L4N Bridge controls {version}\n\n"
            "Close L4D2 and merge bin/neko/plugins into the game directory. "
            "Bridge works without this plugin. Requires L4N SDK v2 HUD support. "
            "See [menu and installation](docs/L4N-BRIDGE-CONTROLS.md).\n", encoding="utf-8")
        receipt = {"version": version, "source_commit": source_commit, "build_id": build_id,
                   "kind": "optional-l4n-plugin", "distribution": "release", "optional_plugin": True,
                   "files": hashes}
        (plugin_output / "BUILD-INFO.json").write_text(json.dumps(receipt, indent=2) + "\n", encoding="utf-8")
        (plugin_output / "SHA256.json").write_text(json.dumps(hashes, indent=2) + "\n", encoding="utf-8")
        print(plugin_output)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    for option in ("client", "host64", "host32", "dxvk", "dxvk-x86", "plugin", "build-info"):
        parser.add_argument("--" + option, type=Path)
    parser.add_argument("--output", type=Path, default=ROOT / "dist")
    parser.add_argument("--patch-only", action="store_true", help="Only package matched Bridge binaries")
    package(parser.parse_args())
